@FunctionalInterface
public interface CheckedBiFunction<T, U, R> {
    R apply(T t, U u) throws Exception;

    static <T, U, R> BiFunction<T, U, Optional<R>> lift(CheckedBiFunction<T, U, R> fn) {
        return (t, u) -> {
            try {
                return Optional.ofNullable(fn.apply(t, u));
            } catch (Exception e) {
                return Optional.empty();
            }
        };
    }
}

public class IORouter {
    public static void main(String[] args) {
        CheckedBiFunction<String, java.nio.file.Path, byte[]> reader = (charset, path) -> 
            java.nio.file.Files.readAllBytes(path);

        // Partial application: fixing the charset/encoding context first
        java.util.function.Function<java.nio.file.Path, Optional<byte[]>> utf8Reader = 
            path -> CheckedBiFunction.lift((c, p) -> java.nio.file.Files.readAllBytes(p)).apply("UTF-8", path);

        java.nio.file.Path target = java.nio.file.Path.of("data.nio");
        Optional<byte[]> data = utf8Reader.apply(target);
    }
}
